import { cn } from '@cascivo/core/pure'
import { builtin, t } from '@cascivo/i18n'
import type { HTMLAttributes } from 'react'
import styles from './typing-indicator.module.css'

export interface TypingIndicatorProps extends HTMLAttributes<HTMLSpanElement> {
  /**
   * Accessible name announced by the status region.
   *
   * @defaultValue `Assistant is typing`
   * @see the component manifest
   */
  ariaLabel?: string
  label?: string
}

export function TypingIndicator({ ariaLabel, label, className, ...props }: TypingIndicatorProps) {
  return (
    <span
      role="status"
      aria-label={ariaLabel ?? label ?? t(builtin.typingIndicator.label)}
      className={cn(styles['typing-indicator'], className as string | undefined)}
      {...props}
    >
      <span className={styles['dot']} aria-hidden="true" />
      <span className={styles['dot']} aria-hidden="true" />
      <span className={styles['dot']} aria-hidden="true" />
    </span>
  )
}

@layer cascivo.component {
  .typing-indicator {
    display: inline-flex;
    align-items: center;
    gap: var(--cascivo-space-1);
    padding-block: var(--cascivo-space-2);
    color: var(--cascivo-typing-indicator-color, var(--cascivo-color-text-muted));
  }

  /* At rest (and under reduced motion) three static dots, which still read as an ellipsis. */
  .dot {
    display: block;
    inline-size: 0.375rem;
    block-size: 0.375rem;
    border-radius: var(--cascivo-radius-full);
    background-color: currentColor;
  }

  /* Decorative loop — opt-in, so a user who expresses no preference gets no motion.
     The stagger is the one `cascivo-dots` documents: 0, 160ms, 320ms. */
  @media (prefers-reduced-motion: no-preference) {
    .dot {
      animation: global(cascivo-dots) var(--cascivo-duration-loop-fast) var(--cascivo-ease-in-out)
        infinite;

      &:nth-child(2) {
        animation-delay: 160ms;
      }

      &:nth-child(3) {
        animation-delay: 320ms;
      }
    }
  }
}

@media (forced-colors: active) {
  .dot {
    background-color: CanvasText;
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'TypingIndicator',
  description:
    'Three bouncing dots that hold a chat message slot while an assistant (or a person) is composing a reply',
  category: 'feedback',
  clientJs: 'none',
  states: [],
  variants: [],
  sizes: [],
  props: [
    {
      name: 'ariaLabel',
      nameVisibility: 'invisible',
      description: 'Accessible name announced by the status region.',
      type: 'string',
      required: false,
      default: 'Assistant is typing',
    },
    {
      name: 'label',
      nameVisibility: 'invisible',
      description:
        'Alias of `ariaLabel` — the same invisible accessible name. Neither is deprecated.',
      type: 'string',
      required: false,
    },
  ],
  tokens: [
    '--cascivo-typing-indicator-color',
    '--cascivo-color-text-muted',
    '--cascivo-radius-full',
    '--cascivo-space-1',
    '--cascivo-space-2',
    '--cascivo-duration-loop-fast',
    '--cascivo-ease-in-out',
  ],
  accessibility: {
    role: 'status',
    wcag: '2.2-AA',
    keyboard: [],
    reducedMotion: true,
    forcedColors: true,
  },
  examples: [
    { title: 'Default', code: '<TypingIndicator />' },
    {
      title: 'In a chat bubble',
      code: '<ChatBubble name="Assistant"><TypingIndicator /></ChatBubble>',
    },
    { title: 'A person typing', code: '<TypingIndicator ariaLabel="Ada is typing" />' },
  ],
  dependencies: ['@cascivo/core', '@cascivo/i18n'],
  tags: ['ai', 'chat', 'typing', 'loading', 'dots', 'thinking'],
  intent: {
    whenToUse: [
      'Holding the place of an assistant reply between sending a prompt and the first token arriving',
      'Showing that another participant in a conversation is composing a message',
    ],
    whenNotToUse: [
      'Naming what the AI is doing ("Searching…", "Generating…") or offering Stop — use AiStatus',
      'Once text has started streaming — render the text; the dots mean nothing has arrived yet',
      'Non-conversational loading — use Spinner or Skeleton',
    ],
    antiPatterns: [
      {
        bad: 'Keeping TypingIndicator below a reply that is already streaming',
        good: 'Swap TypingIndicator for the message content when the first token arrives',
        why: 'Two progress signals at once compete, and the status region would keep claiming nothing has been written',
      },
    ],
    related: [
      {
        name: 'ChatBubble',
        relationship: 'contained-by',
        reason: 'Rendered as the content of a pending assistant ChatBubble',
      },
      {
        name: 'AiStatus',
        relationship: 'alternative',
        reason: 'AiStatus names the phase (thinking / generating) and can offer a Stop button',
      },
      {
        name: 'Spinner',
        relationship: 'alternative',
        reason: 'Spinner suits loading outside a conversation',
      },
    ],
    a11yRationale:
      'role="status" with an accessible name ("Assistant is typing") is announced once when the indicator mounts; the dots are aria-hidden. They bounce only under prefers-reduced-motion: no-preference and otherwise rest as a static ellipsis; forced colours paint them CanvasText',
    content: {
      tone: 'Name who is typing — "Assistant is typing", "Ada is typing"',
    },
    flexibility: [
      {
        area: 'colour',
        level: 'flexible',
        note: 'Override --cascivo-typing-indicator-color (defaults to muted text)',
      },
      {
        area: 'accessible name',
        level: 'strict',
        note: 'Keep the status name — the dots alone carry no meaning for assistive tech',
      },
    ],
  },
}
